style.css:
/* Tema escuro elegante para leitura */
:root {
  --bg: #0D1B2A;      /* azul petróleo profundo */
  --fg: #E0E1DD;      /* texto principal (off-white) */
  --muted: #A7A9AC;   /* texto secundário */
  --accent: #3E8EAC;  /* azul médio para links/destaques */
  --accent-hover: #539FC0;
  --card: #1B263B;    /* superfícies */
  --border: #2C3E50;  /* divisórias sutis */
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--fg);
  font-family: "Georgia", "Times New Roman", serif; /* fonte ideal para leitura longa */
  font-size: 18px;
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

main {
  max-width: 70ch;  /* largura ideal de leitura (~70 caracteres por linha) */
  margin: 0 auto;
  padding: 40px 20px;
}

h1, h2, h3 {
  font-family: "Segoe UI", sans-serif;
  color: var(--fg);
  margin: 1.5em 0 0.6em;
}

p {
  margin: 0 0 1.2em;
}

a {
  color: var(--accent);
  text-decoration: none;
}
a:hover {
  color: var(--accent-hover);
  text-decoration: underline;
}

blockquote {
  margin: 1.5em 0;
  padding: 0.6em 1em;
  border-left: 3px solid var(--accent);
  background: var(--card);
  color: var(--muted);
}

hr {
  border: none;
  border-top: 1px solid var(--border);
  margin: 2em 0;
}
